void flatten(List<Object> nested, List<Object> out) {
    for (Object o : nested) {
        if (o instanceof List<?> inner) {
            flatten((List<Object>) inner, out); // unbounded recursion depth
        } else {
            out.add(o);
        }
    }
}

practices.solution:
void flatten(List<Object> nested, List<Object> out) {
    Deque<Object> stack = new ArrayDeque<>(nested);
    while (!stack.isEmpty()) {
        Object o = stack.pop();
        if (o instanceof List<?> inner) {
            inner.forEach(stack::push); // explicit stack, no JVM call-stack growth
        } else {
            out.add(o);
        }
    }
}

