@Component
class AuthFilter implements Filter {
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) {
        if (!isAuthenticated((HttpServletRequest) req)) { // runs for EVERY request, including OPTIONS preflights, which never carry auth headers
            ((HttpServletResponse) res).sendError(401);
            return;
        }
        chain.doFilter(req, res);
    }
}

practices.solution:
@Component
class AuthFilter implements Filter {
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain) {
        HttpServletRequest httpReq = (HttpServletRequest) req;
        if ("OPTIONS".equals(httpReq.getMethod())) { // let CORS preflight requests through untouched
            chain.doFilter(req, res);
            return;
        }
        if (!isAuthenticated(httpReq)) { ((HttpServletResponse) res).sendError(401); return; }
        chain.doFilter(req, res);
    }
}

