@PostMapping("/upload")
public void upload(@RequestParam MultipartFile file) {
    String detectedType = Tika.detect(file.getInputStream()); // inspects actual file content, not the claimed Content-Type
    if (!ALLOWED_TYPES.contains(detectedType)) throw new UnsupportedFileTypeException();
    String safeName = UUID.randomUUID() + getExtensionFor(detectedType); // server-generated name, no client input in the path
    Files.write(Path.of("/uploads", safeName), file.getBytes());
}

