practices.solution:
@GetMapping("/files/{filename}")
public ResponseEntity<byte[]> download(@PathVariable String filename) throws IOException {
    Path base = Paths.get("/data/uploads").normalize();
    Path resolved = base.resolve(filename).normalize();
    if (!resolved.startsWith(base)) throw new IllegalArgumentException("Invalid file path"); // rejects any traversal attempt
    return ResponseEntity.ok(Files.readAllBytes(resolved));
}

